  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 The Cold War$j$, $j${"readings": [{"title": "Psalm 20 (King James Version)", "url": "/portal/bible/Psalms/20"}], "body": "After World War II the United States and the Soviet Union became rivals in a struggle called the Cold War. It was fought with ideas, spies, money and proxy wars rather than direct battle. The United States stood for democracy and free markets. The Soviet Union ruled by communism and one party control. Eastern Europe fell under Soviet control, and Winston Churchill said an iron curtain had descended across Europe.\n\nAmerica answered with containment, the policy of stopping the spread of communism. The Truman Doctrine of 1947 aided Greece and Turkey. The Marshall Plan helped rebuild Western Europe. In 1948 the Berlin Airlift supplied West Berlin when the Soviets blocked it. NATO formed in 1949 as a defense alliance, and the Soviets built the Warsaw Pact.\n\nWar came in Asia. In the Korean War from 1950 to 1953, American forces under the United Nations defended South Korea from the communist North and the war ended in a stalemate at the 38th parallel. In 1962 the Cuban Missile Crisis brought the world close to nuclear war until the Soviets removed their missiles. At home, fear of communists led to the Red Scare under Senator Joseph McCarthy, and many were accused without proof.\n\nPsalm 20:7 says, Some trust in chariots, and some in horses: but we will remember the name of the LORD our God.\n\nYour task: (1) Define Cold War and containment. (2) Name two programs that carried out containment. (3) Explain the Cuban Missile Crisis.\n\nFlorida standards: SS.912.A.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.6", "script": "Welcome to Unit 6. Listen, after World War II the United States and the Soviet Union became rivals in a struggle called the Cold War. It was fought with ideas, spies, money and proxy wars rather than direct battle. The United States stood for democracy and free markets. The Soviet Union ruled by communism and one party control. Eastern Europe fell under Soviet control, and Winston Churchill said an iron curtain had descended across Europe.\n\nNow watch this. America answered with containment, the policy of stopping the spread of communism. The Truman Doctrine of nineteen forty seven aided Greece and Turkey. The Marshall Plan helped rebuild Western Europe. In nineteen forty eight the Berlin Airlift supplied West Berlin when the Soviets blocked it. NATO formed in nineteen forty nine as a defense alliance, and the Soviets built the Warsaw Pact.\n\nLook at this. War came in Asia. In the Korean War from nineteen fifty to nineteen fifty three, American forces under the United Nations defended South Korea from the communist North, and the war ended in a stalemate at the thirty eighth parallel. In nineteen sixty two the Cuban Missile Crisis brought the world close to nuclear war until the Soviets removed their missiles. At home, fear of communists led to the Red Scare under Senator Joseph McCarthy, and many were accused without proof.\n\nPsalm twenty and seven says, Some trust in chariots, and some in horses: but we will remember the name of the LORD our God.\n\nYour task today. Define Cold War and containment. Name two programs that carried out containment. And explain the Cuban Missile Crisis. Take the four question check.\n\nOur trust is in the Lord. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 The Cold War$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 The Civil Rights Movement$j$, $j${"readings": [{"title": "Proverbs 31 (King James Version)", "url": "/portal/bible/Proverbs/31"}], "body": "For a century after the Civil War, African Americans were denied equal rights by Jim Crow laws. The modern Civil Rights Movement began to change that, using courts, peaceful protest and the witness of the church.\n\nLandmark events:\nBrown v. Board of Education (1954): The Supreme Court ruled that separate schools are unequal, overturning Plessy v. Ferguson. In 1957 President Eisenhower sent troops to protect the Little Rock Nine.\nMontgomery Bus Boycott (1955 to 1956): After Rosa Parks refused to give up her seat, Dr. Martin Luther King Jr. led a boycott of the bus system for 381 days.\nSit ins and Freedom Rides (1960 and 1961) challenged segregated lunch counters and buses.\nThe March on Washington (1963): King gave his I Have a Dream speech to a quarter million people.\nBirmingham, with its Letter from a Birmingham Jail, showed the cost of nonviolence.\nThe Civil Rights Act of 1964 banned segregation in public places and job discrimination. The Voting Rights Act of 1965 ended barriers like literacy tests after the marches from Selma. The Twenty Fourth Amendment banned the poll tax.\n\nLeaders included King, Rosa Parks, John Lewis, Fannie Lou Hamer and Thurgood Marshall, and others such as Malcolm X urged a different path. Dr. King was assassinated in Memphis in 1968.\n\nAmos 5:24 says, But let judgment run down as waters, and righteousness as a mighty stream.\n\nYour task: (1) Explain why Brown v. Board mattered. (2) Describe the Montgomery Bus Boycott. (3) Name two laws from 1964 and 1965 and what each did.\n\nFlorida standards: SS.912.A.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.7", "script": "Welcome back. Listen, for a century after the Civil War, African Americans were denied equal rights by Jim Crow laws. The modern Civil Rights Movement began to change that, using courts, peaceful protest and the witness of the church.\n\nNow watch this. In nineteen fifty four, in Brown v. Board of Education, the Supreme Court ruled that separate schools are unequal, overturning Plessy v. Ferguson. In nineteen fifty seven President Eisenhower sent troops to protect the Little Rock Nine. In nineteen fifty five Rosa Parks refused to give up her seat, and Dr. Martin Luther King Jr. led a boycott of the Montgomery bus system for three hundred eighty one days. Sit ins and Freedom Rides challenged segregated lunch counters and buses. In nineteen sixty three King gave his I Have a Dream speech to a quarter million people at the March on Washington.\n\nLook at this. The Civil Rights Act of nineteen sixty four banned segregation in public places and job discrimination. The Voting Rights Act of nineteen sixty five ended barriers like literacy tests after the marches from Selma. The Twenty Fourth Amendment banned the poll tax. Leaders included King, Rosa Parks, John Lewis, Fannie Lou Hamer and Thurgood Marshall. Dr. King was assassinated in Memphis in nineteen sixty eight.\n\nAmos five and twenty four says, But let judgment run down as waters, and righteousness as a mighty stream.\n\nYour task today. Explain why Brown v. Board mattered. Describe the Montgomery Bus Boycott. And name two laws from nineteen sixty four and sixty five and what each did. Take the four question check.\n\nJustice rolls like a mighty stream. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 The Civil Rights Movement$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Vietnam, Watergate and the Years of Change$j$, $j${"readings": [{"title": "Proverbs 11 (King James Version)", "url": "/portal/bible/Proverbs/11"}], "body": "The 1960s and 1970s brought deep change. Presidents John Kennedy, Lyndon Johnson and Richard Nixon led through crises. Kennedy was assassinated in 1963. Johnson launched the Great Society, including Medicare, Medicaid and federal aid to education, and a War on Poverty.\n\nThe Vietnam War grew from containment. America sent advisers, then, after the Gulf of Tonkin Resolution in 1964, hundreds of thousands of troops to defend South Vietnam against the communist North. The Tet Offensive of 1968 and television coverage turned many Americans against the war. Protests divided the nation. Nixon began Vietnamization and withdrew American troops in 1973. South Vietnam fell in 1975. More than 58,000 Americans died.\n\nOther movements arose: the women's movement, led by Betty Friedan, the farmworkers' movement under Cesar Chavez, and the American Indian Movement. The Twenty Sixth Amendment lowered the voting age to 18 in 1971.\n\nWatergate was a scandal in which men working for Nixon's campaign broke into Democratic offices in 1972 and Nixon tried to cover it up. Facing impeachment, he resigned in August 1974, the only president to do so. Gerald Ford pardoned him. The nation lost trust in government, yet the system of checks and balances held.\n\nProverbs 11:14 says, Where no counsel is, the people fall: but in the multitude of counsellors there is safety.\n\nYour task: (1) Name two Great Society programs. (2) Explain why the Vietnam War divided Americans. (3) Explain Watergate and what it shows about the rule of law.\n\nFlorida standards: SS.912.A.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.7", "script": "Welcome back. Listen, the nineteen sixties and seventies brought deep change. Presidents John Kennedy, Lyndon Johnson and Richard Nixon led through crises. Kennedy was assassinated in nineteen sixty three. Johnson launched the Great Society, including Medicare, Medicaid and federal aid to education, and a War on Poverty.\n\nNow watch this. The Vietnam War grew from containment. America sent advisers, then, after the Gulf of Tonkin Resolution in nineteen sixty four, hundreds of thousands of troops to defend South Vietnam against the communist North. The Tet Offensive of nineteen sixty eight and television coverage turned many Americans against the war. Protests divided the nation. Nixon began Vietnamization and withdrew American troops in nineteen seventy three. South Vietnam fell in nineteen seventy five. More than fifty eight thousand Americans died.\n\nLook at this. Other movements arose, including the women's movement led by Betty Friedan, the farmworkers' movement under Cesar Chavez, and the American Indian Movement. The Twenty Sixth Amendment lowered the voting age to eighteen. Watergate was a scandal in which men working for Nixon's campaign broke into Democratic offices in nineteen seventy two and Nixon tried to cover it up. Facing impeachment, he resigned in August nineteen seventy four. The nation lost trust in government, yet checks and balances held.\n\nProverbs eleven and fourteen says, Where no counsel is, the people fall: but in the multitude of counsellors there is safety.\n\nYour task today. Name two Great Society programs. Explain why the Vietnam War divided Americans. And explain Watergate and what it shows about the rule of law. Take the four question check.\n\nPray for leaders and for truth. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Vietnam, Watergate and the Years of Change$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Reagan, the End of the Cold War and Modern America$j$, $j${"readings": [{"title": "2 Chronicles 7 (King James Version)", "url": "/portal/bible/2Chronicles/7"}], "body": "In 1980 Americans elected Ronald Reagan, who promised lower taxes, less regulation and a strong defense. His policies cut taxes and inflation, and the economy grew, though the national debt also grew. Reagan called the Soviet Union an evil empire, and then negotiated with Soviet leader Mikhail Gorbachev. In 1987 they signed a treaty removing intermediate range missiles. The Berlin Wall fell in 1989, and the Soviet Union dissolved in 1991, ending the Cold War.\n\nThe 1990s brought the Persian Gulf War of 1991 under President George H. W. Bush to free Kuwait, and strong economic growth and the rise of the internet under Bill Clinton. Clinton was impeached in 1998 but not removed.\n\nOn September 11, 2001, terrorists attacked New York and Washington, killing nearly 3,000 people. President George W. Bush launched the war on terror, with wars in Afghanistan and Iraq, and the Department of Homeland Security was formed. The financial crisis of 2008 led to a deep recession. In 2008 Barack Obama became the first African American president. Since then the nation has faced debates over health care, immigration, technology, a global pandemic in 2020 and deep political division.\n\nThrough every age the American people have relied on faith, family and service. 2 Chronicles 7:14 says, If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.\n\nYour task: (1) Name two ways the Cold War ended. (2) Explain what happened on September 11, 2001 and how the nation responded. (3) Tell one challenge facing America today and how a Christian citizen might respond.\n\nFlorida standards: SS.912.A.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.7", "script": "Welcome back. Listen, in nineteen eighty Americans elected Ronald Reagan, who promised lower taxes, less regulation and a strong defense. His policies cut taxes and inflation, and the economy grew, though the national debt also grew. Reagan called the Soviet Union an evil empire, and then negotiated with Soviet leader Mikhail Gorbachev. In nineteen eighty seven they signed a treaty removing intermediate range missiles. The Berlin Wall fell in nineteen eighty nine, and the Soviet Union dissolved in nineteen ninety one, ending the Cold War.\n\nNow watch this. The nineteen nineties brought the Persian Gulf War of nineteen ninety one under President George H. W. Bush to free Kuwait, and strong economic growth and the rise of the internet under Bill Clinton.\n\nLook at this. On September eleventh, two thousand one, terrorists attacked New York and Washington, killing nearly three thousand people. President George W. Bush launched the war on terror, with wars in Afghanistan and Iraq, and the Department of Homeland Security was formed. The financial crisis of two thousand eight led to a deep recession. In two thousand eight Barack Obama became the first African American president. Since then the nation has faced debates over health care, immigration, technology, a global pandemic in two thousand twenty and deep political division.\n\nThrough every age the American people have relied on faith, family and service. Second Chronicles seven and fourteen says, If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.\n\nYour task today. Name two ways the Cold War ended. Explain what happened on September eleventh, two thousand one, and how the nation responded. And tell one challenge facing America today and how a Christian citizen might respond. Take the four question check.\n\nPray for our nation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Reagan, the End of the Cold War and Modern America$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Postwar America and the Modern Nation$j$, $j${"prompt": "Write an essay answering this question: How did the Cold War and the Civil Rights Movement shape modern America? Use complete sentences and label each part. 2 Chronicles 7:14 says, If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.\n\nPart 1: Explain the Cold War, containment and three events that show it.\nPart 2: Explain three events or laws of the Civil Rights Movement and name three leaders.\nPart 3: Explain why the Vietnam War and Watergate shook trust in government.\nPart 4: Explain how the Cold War ended.\nPart 5: Describe two major events since 1990 and their effects.\nPart 6: Give your thesis on the greatest challenge facing America today, using evidence from the unit and one KJV verse.", "rubric": "70 points. Cold War: 12 points. Civil Rights Movement: 14 points. Vietnam and Watergate: 10 points. End of the Cold War: 6 points. Modern events: 8 points. Thesis and evidence: 16 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Postwar America and the Modern Nation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Freedom, Faith and the Future of America$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why Dr. King used nonviolence and how the church shaped the Civil Rights Movement, (2) tells what a citizen should do when government fails the people, as in Vietnam or Watergate, (3) describes one hope you have for the United States, and (4) connects your answer to Amos 5:24, which says, But let judgment run down as waters, and righteousness as a mighty stream. Then write a respectful reply of at least 40 words to another student, or answer this question: Why did the Berlin Wall matter? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Freedom, Faith and the Future of America$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: The Cold War$j$, $j${"questions": [{"q": "Containment was the policy of:", "options": ["Joining the Soviet Union", "Ending trade", "Building a canal", "Stopping the spread of communism"]}, {"q": "The Marshall Plan:", "options": ["Helped rebuild Western Europe", "Ended Prohibition", "Started the Korean War", "Created the UN"]}, {"q": "NATO was formed in:", "options": ["1914", "1949", "1776", "1989"]}, {"q": "The Cuban Missile Crisis occurred in:", "options": ["1929", "1962", "1991", "1945"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: The Cold War$j$);
