  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,0}'::int[], array[$j$It overturned Plessy v. Ferguson in schools.$j$,$j$It lasted 381 days and was led by Dr. King.$j$,$j$It outlawed barriers like literacy tests.$j$,$j$It was in August 1963.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The Civil Rights Movement$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Vietnam, Watergate and the Years of Change$j$, $j${"questions": [{"q": "The Great Society was a program of President:", "options": ["Richard Nixon", "Franklin Roosevelt", "Lyndon Johnson", "Herbert Hoover"]}, {"q": "The Vietnam War ended for American troops in:", "options": ["1991", "1945", "1953", "1973"]}, {"q": "The Twenty Sixth Amendment lowered the voting age to:", "options": ["25", "21", "16", "18"]}, {"q": "President Nixon resigned because of:", "options": ["The Cuban Missile Crisis", "Watergate", "Prohibition", "Pearl Harbor"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Vietnam, Watergate and the Years of Change$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,1}'::int[], array[$j$It included Medicare and Medicaid.$j$,$j$South Vietnam fell in 1975.$j$,$j$It was ratified in 1971.$j$,$j$He faced impeachment in 1974.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Vietnam, Watergate and the Years of Change$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Reagan, the End of the Cold War and Modern America$j$, $j${"questions": [{"q": "The Berlin Wall fell in:", "options": ["1945", "1989", "2001", "1961"]}, {"q": "The Soviet Union dissolved in:", "options": ["1945", "1962", "1991", "1980"]}, {"q": "The September 11, 2001 attacks led to the war in:", "options": ["Afghanistan", "Korea", "Vietnam", "Cuba"]}, {"q": "The first African American president was:", "options": ["Barack Obama", "Bill Clinton", "George W. Bush", "Ronald Reagan"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Reagan, the End of the Cold War and Modern America$j$);
