  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: The Cold War, Civil Rights and Modern America$j$, $j${"questions": [{"q": "The Truman Doctrine aided:", "options": ["Cuba and Mexico", "Spain and Italy", "Greece and Turkey", "Japan and China"]}, {"q": "The Korean War ended near the:", "options": ["38th parallel", "Rio Grande", "Panama Canal", "Berlin Wall"]}, {"q": "Which law banned segregation in public places?", "options": ["Civil Rights Act of 1964", "Homestead Act", "Dawes Act", "Sherman Act"]}, {"q": "Rosa Parks refused to:", "options": ["Leave Alabama", "Join a union", "Sign a treaty", "Give up her bus seat"]}, {"q": "The Gulf of Tonkin Resolution led to:", "options": ["The New Deal", "The Marshall Plan", "Greater American involvement in Vietnam", "The Berlin Airlift"]}, {"q": "Who negotiated with Ronald Reagan to reduce nuclear missiles?", "options": ["Fidel Castro", "Mikhail Gorbachev", "Joseph Stalin", "Mao Zedong"]}, {"q": "The September 11 attacks occurred in:", "options": ["1991", "2020", "2001", "1963"]}, {"q": "The Department of Homeland Security was created after:", "options": ["September 11, 2001", "Watergate", "The Cuban Missile Crisis", "Pearl Harbor"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Cold War, Civil Rights and Modern America$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,3,2,1,2,0}'::int[], array[$j$It was a first step in containment.$j$,$j$The war ended in a stalemate.$j$,$j$It also banned job discrimination.$j$,$j$Her action began the Montgomery Bus Boycott.$j$,$j$It gave President Johnson broad war powers.$j$,$j$They signed a treaty in 1987.$j$,$j$Nearly 3,000 people died.$j$,$j$It aimed to protect the nation from attack.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: The Cold War, Civil Rights and Modern America$j$ on conflict (item_id) do nothing;
